// === Tab: mySketch ===
function setup() {
  createCanvas(1000, 1000, WEBGL);
  angleMode(DEGREES);
  colorMode(HSB);
  noStroke();
}

function draw() {
  background(0);
  orbitControl();
  pointLight(100, 20, 100, 0, -800, 200);
  pointLight(200, 20, 100, 0, 800, 200);

  for (let x = -300; x < 360; x += 60) {
    for (let y = -300; y < 360; y += 60) {
      push();
      translate(x, y, -400);
      rotateZ(noise(x/600.0, y/600.0, (millis()/10000.0))*360.0-180.0);
      let len = 30;
      for (let i = 5; i > 0; i--) {
        translate(0, 0, 0.6 * i * len);
        rotateY(noise((x/400.0) + millis()/7000.0, y/400.0, (millis()/12000.0))*50.0-25.0);
        translate(0, 0, 0.5 * i * len);
        push();
        rotateX(90);
        shininess(5);
        specularMaterial(70+(i*20), i*15, 80);
        cylinder(i * 3, i * len, 7, 1, 1, 1);
        pop();
      }
      pop();
    }
  }

}
